#include <stdio.h>
/*
 * ex09：三段论有效性 —— 用「有限域穷举全部解释」来判有效
 * 为什么：「有效」不是「结论听起来对」，而是「所有让前提为真的解释，都让结论为真」。
 *        域取 5 个元素、3 个谓词，共有 2^15 = 32768 种解释，可以全部枚举。
 * 本例验证有效式：∀x(M→P), ∀x(P→Q) ⊨ ∀x(M→Q)
 *        并给出无效式的反例：∀x(P→Q), Q(a) ⊭ P(a)（肯定后件）
 */
#define N 5
int main(void) {
    int total = 0, premise_models = 0, violations = 0;
    for (int M = 0; M < (1 << N); M++)
        for (int P = 0; P < (1 << N); P++)
            for (int Q = 0; Q < (1 << N); Q++) {
                total++;
                int p1 = 1, p2 = 1;
                for (int x = 0; x < N; x++) {
                    int m = (M >> x) & 1, p = (P >> x) & 1, q = (Q >> x) & 1;
                    if (m && !p) p1 = 0;            /* ∀x(M->P) */
                    if (p && !q) p2 = 0;            /* ∀x(P->Q) */
                }
                if (!(p1 && p2)) continue;
                premise_models++;
                int concl = 1;
                for (int x = 0; x < N; x++)
                    if (((M >> x) & 1) && !((Q >> x) & 1)) concl = 0;
                if (!concl) violations++;
            }
    printf("domain size = %d, predicates = 3, interpretations = %d\n", N, total);
    printf("interpretations satisfying both premises = %d\n", premise_models);
    printf("of those, violating the conclusion     = %d\n", violations);
    printf("=> the syllogism is %s\n\n", violations == 0 ? "VALID" : "INVALID");

    /* 肯定后件的反例：找一个 P->Q 全真、Q(a) 真、但 P(a) 假的解释 */
    printf("invalid form check:  P->Q (all x),  Q(a)  =>  P(a) ?\n");
    for (int P = 0; P < (1 << N); P++)
        for (int Q = 0; Q < (1 << N); Q++) {
            int all = 1;
            for (int x = 0; x < N; x++) if (((P >> x) & 1) && !((Q >> x) & 1)) all = 0;
            if (!all) continue;
            for (int a = 0; a < N; a++)
                if (((Q >> a) & 1) && !((P >> a) & 1)) {
                    printf("counterexample: P={");
                    for (int x = 0; x < N; x++) printf("%d", (P >> x) & 1);
                    printf("}, Q={");
                    for (int x = 0; x < N; x++) printf("%d", (Q >> x) & 1);
                    printf("}, a=%d  (Q(a)=1 but P(a)=0)\n", a);
                    return 0;
                }
        }
    printf("none found\n");
    return 0;
}
